import{c as o,Q as d,j as e,m as i}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E7%9F%A9%E9%98%B5%E7%BC%96%E7%A8%8B%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%E7%A4%BA%E6%84%8F%E5%9B%BE-40.Dp2JOIw5.png",u="/assets/%E5%9B%BE3-%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%B9%B6%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.DPtgili7.png",s="/assets/%E5%9B%BE3-%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%B9%B6%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE-41.DiavMlc7.png",B=JSON.parse('{"title":"TQueBind简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"TQueBind简介","slug":"tquebind简介"},{"level":2,"title":"模板参数","slug":"模板参数"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TQueBind/TQueBind简介.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TQueBind/TQueBind简介.md"}'),c={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TQueBind/TQueBind简介.md"};function n(r,t,T,a,p,g){return d(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="tquebind简介" tabindex="-1">TQueBind简介 <a class="header-anchor" href="#tquebind简介" aria-label="Permalink to &quot;TQueBind简介&quot;">​</a></h1><p>TQueBind绑定源逻辑位置和目的逻辑位置，根据源位置和目的位置，来确定内存分配的位置 、插入对应的同步事件，帮助开发者解决内存分配和管理、同步等问题。Tque是TQueBind的简化模式。通常情况下开发者使用TQue进行编程，TQueBind对外提供一些特殊数据通路的内存管理和同步控制，涉及这些通路时可以直接使用TQueBind。</p><p>如下图的数据通路示意图所示，红色线条和蓝色线条的通路可通过TQueBind定义表达，蓝色线条的通路可通过TQue进行简化表达。</p><p><img src="'+l+'" alt=""></p><p><strong>表 1</strong> TQueBind和TQue对于数据通路的表达</p><table tabindex="0"><thead><tr><th>数据通路</th><th>TQueBind定义</th><th>TQue定义</th></tr></thead><tbody><tr><td>GM-&gt;VECIN</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock653942891212&quot;&gt;TQueBind&lt;TPosition::GM, TPosition::VECIN, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock149969438127&quot;&gt;TQue&lt;TPosition::VECIN, 1&gt;&lt;/pre&gt;</td></tr><tr><td>VECOUT-&gt;GM</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock330274851210&quot;&gt;TQueBind&lt;TPosition::VECOUT, TPosition::GM, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock192801353131214&quot;&gt;TQue&lt;TPosition::VECOUT, 1&gt;&lt;/pre&gt;</td></tr><tr><td>VECIN-&gt;VECOUT</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock563125191319&quot;&gt;TQueBind&lt;TPosition::VECIN, TPosition::VECOUT, 1&gt;&lt;/pre&gt;</td><td>-</td></tr><tr><td>GM-&gt;A1</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock19855119151320&quot;&gt;TQueBind&lt;TPosition::GM, TPosition::A1, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock1035819162139&quot;&gt;TQue&lt;TPosition::A1, 1&gt;&lt;/pre&gt;</td></tr><tr><td>GM-&gt;B1</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock9773162110138&quot;&gt;TQueBind&lt;TPosition::GM, TPosition::B1, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock4847182510138&quot;&gt;TQue&lt;TPosition::B1, 1&gt;&lt;/pre&gt;</td></tr><tr><td>GM-&gt;C1</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock149532378137&quot;&gt;TQueBind&lt;TPosition::GM, TPosition::C1, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock845074318134&quot;&gt;TQue&lt;TPosition::C1, 1&gt;&lt;/pre&gt;</td></tr><tr><td>A1-&gt;A2</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock54201349101318&quot;&gt;TQueBind&lt;TPosition::A1, TPosition::A2, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock6454195316132&quot;&gt;TQue&lt;TPosition::A2, 1&gt;&lt;/pre&gt;</td></tr><tr><td>B1-&gt;B2</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock1836165801319&quot;&gt;TQueBind&lt;TPosition::B1, TPosition::B2, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock14155220141&quot;&gt;TQue&lt;TPosition::B2, 1&gt;&lt;/pre&gt;</td></tr><tr><td>C1-&gt;C2</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock188651767149&quot;&gt;TQueBind&lt;TPosition::C1, TPosition::C2, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock967861221417&quot;&gt;TQue&lt;TPosition::C2, 1&gt;&lt;/pre&gt;</td></tr><tr><td>CO1-&gt;CO2</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock19862141621414&quot;&gt;TQueBind&lt;TPosition::CO1, TPosition::CO2, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock1388062161412&quot;&gt;TQue&lt;TPosition::CO1, 1&gt;&lt;/pre&gt;</td></tr><tr><td>CO2-&gt;GM</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock123131826191417&quot;&gt;TQueBind&lt;TPosition::CO2, TPosition::GM, 1&gt;&lt;/pre&gt;</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock1437413211410&quot;&gt;TQue&lt;TPosition::CO2, 1&gt;&lt;/pre&gt;</td></tr><tr><td>VECOUT-&gt;A1/B1/C1</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock2976143713148&quot;&gt;TQueBind&lt;TPosition::VECOUT, TPosition::A1, 1&gt; TQueBind&lt;TPosition::VECOUT, TPosition::B1, 1&gt; TQueBind&lt;TPosition::VECOUT, TPosition::C1, 1&gt;&lt;/pre&gt;</td><td>-</td></tr><tr><td>CO2-&gt;VECIN</td><td>&lt;pre class=&quot;codeblock&quot; id=&quot;codeblock18142184301418&quot;&gt;TQueBind&lt;TPosition::CO2, TPosition::VECIN, 1&gt;&lt;/pre&gt;</td><td>-</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>上述表格中的Cube相关数据通路建议使用Cube高阶API（如Matmul）实现，直接使用TQueBind控制会相对复杂。</p></div><p>下面通过两个具体的示例展示了矢量编程场景下TQueBind的使用方法：</p><ul><li><p>如下的编程范式示例，图中的两个队列分别绑定的是GM VECIN和VECOUT GM。</p><p><img src="'+u+'" alt=""></p></li><li><p>如果不需要进行Vector计算，比如仅需要做格式随路转换等场景，可对上述流程进行优化，对VECIN和VECOUT进行绑定，绑定的效果可以实现输入输出使用相同buffer，实现double buffer。</p><p><img src="'+s+'" alt=""></p></li></ul><h2 id="模板参数" tabindex="-1">模板参数 <a class="header-anchor" href="#模板参数" aria-label="Permalink to &quot;模板参数&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition src, TPosition dst, int32_t depth, auto mask = 0&gt; class TQueBind {...};</span></span></code></pre></div><p><strong>表 2</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>源逻辑位置，支持的TPosition可以为VECIN、VECOUT、A1、A2、B1、B2、CO1、CO2。关于TPosition的具体介绍请参考TPosition。支持的src和dst组合请参考表1。</td></tr><tr><td>dst</td><td>目的逻辑位置，TPosition可以为VECIN、VECOUT、A1、A2、B1、B2、CO1、CO2。</td></tr><tr><td>depth</td><td>TQue的深度，一般不超过4。</td></tr><tr><td>mask</td><td>如果用户在某一个Que上，数据搬运的时候需要做转换，可以设置为0或1。一般不需要用户配置，默认为0。 设置为0，代表数据格式从ND转换为NZ，目前仅支持TPosition为A1或B1。</td></tr></tbody></table>',13)])])}const b=o(c,[["render",n]]);export{B as __pageData,b as default};
